  roster.units.set('TinyDeadHead', [tank]);
  roster.units.set('HeavyMiniBoss', [{ ...tank }]);
  roster.units.set('Balanced', [{ ...tank }]);
  expect(roster.lookupKey(tankRosterIdentity(tank))).toBe('Balanced');
